### Persist Item state

The `@forceState` argument can be used to programmatically control individual Accordion Items. For example, use `@onClickToggle` to respond to the user’s click, save the open/close state, then use `@forceState` to persist the state if the screen refreshes.


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';
import { service } from '@ember/service';
import type Owner from '@ember/owner';
import FastBootService from 'ember-cli-fastboot/services/fastboot';

import { HdsAccordion } from '@hashicorp/design-system-components/components';
import type { HdsAccordionSignature } from '@hashicorp/design-system-components/components/hds/accordion/index';

const STORAGE_KEY = 'website:accordion:item-2-state';

export default class LocalComponent extends Component {
  @tracked itemState: HdsAccordionSignature['Args']['forceState'];
  @service declare fastboot: FastBootService;

  constructor(owner: Owner, args: Record<string, never>) {
    super(owner, args);
    if (!this.fastboot.isFastBoot) {
      this.itemState = (sessionStorage.getItem(STORAGE_KEY) ??
        'open') as HdsAccordionSignature['Args']['forceState'];
    }
  }

  onItemToggle = () => {
    this.itemState = this.itemState === 'open' ? 'close' : 'open';
    sessionStorage.setItem(STORAGE_KEY, this.itemState);
  };

  <template>
    <HdsAccordion as |A|>
      <A.Item>
        <:toggle>Item one</:toggle>
        <:content>
          Additional content for item one
        </:content>
      </A.Item>
      <A.Item
        @onClickToggle={{this.onItemToggle}}
        @forceState={{this.itemState}}
      >
        <:toggle>Item two</:toggle>
        <:content>
          Item open on page load. Click to close then refresh the window. The
          Item will remember its state and remain closed.
        </:content>
      </A.Item>
      <A.Item>
        <:toggle>Item three</:toggle>
        <:content>
          Additional content for item three
        </:content>
      </A.Item>
    </HdsAccordion>
  </template>
}
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Accordion as |A|>
  <A.Item>
    <:toggle>Item one</:toggle>
    <:content>
      Additional content for item one
    </:content>
  </A.Item>
  <A.Item @onClickToggle={{this.onItemToggle}} @forceState={{this.itemState}}>
    <:toggle>Item two</:toggle>
    <:content>
      Item open on page load. Click to close then refresh the window. The Item will remember its state and remain
      closed.
    </:content>
  </A.Item>
  <A.Item>
    <:toggle>Item three</:toggle>
    <:content>
      Additional content for item three
    </:content>
  </A.Item>
</Hds::Accordion>
```

```javascript title="Classic Ember backing class (.js)"
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { tracked } from '@glimmer/tracking';
import { service } from '@ember/service';

const STORAGE_KEY = 'website:accordion:item-2-state';

export default class LocalComponent extends Component {
  @tracked itemState;
  @service fastboot;

  constructor(owner, args) {
    super(owner, args);
    if (!this.fastboot.isFastBoot) {
      this.itemState = sessionStorage.getItem(STORAGE_KEY) ?? 'open';
    }
  }

  @action
  onItemToggle() {
    this.itemState = this.itemState === 'open' ? 'close' : 'open';
    sessionStorage.setItem(STORAGE_KEY, this.itemState);
  }
}
```

### Dismissal

To enable dismissibility, pass a callback function to the `onDismiss` argument. This will add a dismiss button to the Alert. When that button is clicked, the callback function will be executed. 

Given the variety of use cases and contexts in which alerts are used across products, application teams will need to implement the callback function.


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';

import { HdsAlert } from '@hashicorp/design-system-components/components';

export default class LocalComponent extends Component {
  noop = () => {
    //
  };

  <template>
    <HdsAlert @type="inline" @color="warning" @onDismiss={{this.noop}} as |A|>
      <A.Title>Title here</A.Title>
      <A.Description>Description here</A.Description>
    </HdsAlert>
  </template>
}
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Alert @type="inline" @color="warning" @onDismiss={{this.noop}} as |A|>
  <A.Title>Title here</A.Title>
  <A.Description>Description here</A.Description>
</Hds::Alert>
```

```javascript title="Classic Ember backing class (.js)"
import Component from '@glimmer/component';
import { action } from '@ember/object';

export default class LocalComponent extends Component {
  @action
  noop() {
    //
  }
}
```

### Actions

Actions can be passed to the component using one of the suggested `Button` or `LinkStandalone` contextual components.


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';
import { on } from '@ember/modifier';

import { HdsAlert } from '@hashicorp/design-system-components/components';

export default class LocalComponent extends Component {
  yourOnClickFunction = () => {
    console.log('Clicked the button in the "alert"!');
  };

  <template>
    <HdsAlert @type="inline" as |A|>
      <A.Title>Title here</A.Title>
      <A.Description>Description here</A.Description>
      <A.Button
        @text="Your action"
        @color="secondary"
        {{on "click" this.yourOnClickFunction}}
      />
      <A.LinkStandalone
        @color="secondary"
        @icon="arrow-right"
        @iconPosition="trailing"
        @text="Another action"
        @href="#"
      />
    </HdsAlert>
  </template>
}
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Alert @type="inline" as |A|>
  <A.Title>Title here</A.Title>
  <A.Description>Description here</A.Description>
  <A.Button @text="Your action" @color="secondary" {{on "click" this.yourOnClickFunction}} />
  <A.LinkStandalone @color="secondary" @icon="arrow-right" @iconPosition="trailing" @text="Another action" @href="#" />
</Hds::Alert>
```

```javascript title="Classic Ember backing class (.js)"
import Component from '@glimmer/component';
import { action } from '@ember/object';

export default class LocalComponent extends Component {
  @action
  yourOnClickFunction() {
    console.log('Clicked the button in the "alert"!');
  }
}
```

### Generic content

Use the `GenericContent` and `GenericFooter` contextual components to insert custom content. Generic Content will appear after the Title and Description and above the Actions while the Generic Footer will appear at the bottom of the Alert content below the actions. Application teams will need to implement spacing, layout, and styling for generic content.


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';
import { on } from '@ember/modifier';

import { HdsAlert } from '@hashicorp/design-system-components/components';

export default class LocalComponent extends Component {
  yourOnClickFunction = () => {
    console.log('Clicked the button in the "alert"!');
  };
  <template>
    <HdsAlert @type="inline" as |A|>
      <A.Title>Title here</A.Title>
      <A.Description>Description here</A.Description>
      <A.GenericContent>
        [your custom content here]
      </A.GenericContent>
      <A.Button
        @text="Your action"
        @color="secondary"
        {{on "click" this.yourOnClickFunction}}
      />
      <A.LinkStandalone
        @color="secondary"
        @icon="arrow-right"
        @iconPosition="trailing"
        @text="Another action"
        @href="#"
      />
      <A.GenericFooter>
        [your custom footer here]
      </A.GenericFooter>
    </HdsAlert>
  </template>
}
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Alert @type="inline" as |A|>
  <A.Title>Title here</A.Title>
  <A.Description>Description here</A.Description>
  <A.GenericContent>
    [your custom content here]
  </A.GenericContent>
  <A.Button @text="Your action" @color="secondary" {{on "click" this.yourOnClickFunction}} />
  <A.LinkStandalone @color="secondary" @icon="arrow-right" @iconPosition="trailing" @text="Another action" @href="#" />
  <A.GenericFooter>
    [your custom footer here]
  </A.GenericFooter>
</Hds::Alert>
```

