### ExtraBefore & ExtraAfter

Custom content can be added either before or after the `AppFooter` main content. The layout of this content is inline with other content by default.


```gts title="Modern Ember (.gts)"
import type { TemplateOnlyComponent } from '@ember/component/template-only';

import { HdsAppFooter } from '@hashicorp/design-system-components/components';

import DocPlaceholder from 'website/components/doc/placeholder';

const LocalComponent: TemplateOnlyComponent = <template>
  <HdsAppFooter as |AF|>
    <AF.ExtraBefore>
      <DocPlaceholder
        @text="Extra Content Before"
        @height="2em"
        @width="fit-content"
        class="doc-app-footer-demo-placeholder"
      />
    </AF.ExtraBefore>
    <AF.LegalLinks />
    <AF.ExtraAfter>
      <DocPlaceholder
        @text="Extra Content After"
        @height="2em"
        @width="fit-content"
        class="doc-app-footer-demo-placeholder"
      />
    </AF.ExtraAfter>
  </HdsAppFooter>
</template>;

export default LocalComponent;
```

```handlebars title="Classic Ember (.hbs)"
<Hds::AppFooter as |AF|>
  <AF.ExtraBefore>
    <Doc::Placeholder
      @text="Extra Content Before"
      @height="2em"
      @width="fit-content"
      class="doc-app-footer-demo-placeholder"
    />
  </AF.ExtraBefore>
  <AF.LegalLinks />
  <AF.ExtraAfter>
    <Doc::Placeholder
      @text="Extra Content After"
      @height="2em"
      @width="fit-content"
      class="doc-app-footer-demo-placeholder"
    />
  </AF.ExtraAfter>
</Hds::AppFooter>
```

### Layout

The `AppHeader` exposes three “slots” (named blocks) where consumers can yield the navigation content and also add business logic to control the content.

The `<:logo>` block should contain the `AppHeader::HomeLink` which is provided as a child component.

The other two slots are intended for consumer-provided controls. The `<:globalActions>` block should typically contain a “context switcher” (sometimes called an “org switcher” or “project switcher”). The `<:utilityActions>` block is used to provide utilities including “Help” and “User” menus and, optionally, “Search”.


```gts title="Modern Ember (.gts)"
import type { TemplateOnlyComponent } from '@ember/component/template-only';

import { HdsAppHeader } from '@hashicorp/design-system-components/components';

import DocPlaceholder from 'website/components/doc/placeholder';

const LocalComponent: TemplateOnlyComponent = <template>
  {{! for demo purposes, we set @hasA11yRefocus to false but in your app it will
probably need to be set to true (or omitted to rely on defaults) }}
  <HdsAppHeader @hasA11yRefocus={{false}}>
    <:logo>
      <DocPlaceholder
        @height="2em"
        @width="auto"
        @text="HomeLink"
        @background="#e4e4e4"
      />
    </:logo>

    <:globalActions>
      <DocPlaceholder
        @height="2em"
        @width="auto"
        @text="OrgSwitcher"
        @background="#e4e4e4"
      />
    </:globalActions>

    <:utilityActions>
      <DocPlaceholder
        @height="2em"
        @width="auto"
        @text="HelpMenu"
        @background="#e4e4e4"
      />
      <DocPlaceholder
        @height="2em"
        @width="auto"
        @text="UserMenu"
        @background="#e4e4e4"
      />
    </:utilityActions>
  </HdsAppHeader>
</template>;

export default LocalComponent;
```

```handlebars title="Classic Ember (.hbs)"
