      @badge="Alpha"
      @hasSubItems={{true}}
    />
    <Nav.Title>Default Org</Nav.Title>
    <Nav.Link @text="HashiCorp Virtual Networks" @icon="network" @href="#" />
    <Nav.Link
      @text="Access control (IAM)"
      @icon="users"
      @href="#"
      @hasSubItems={{true}}
    />
    <Nav.Link
      @text="Billing"
      @icon="credit-card"
