#### With loading state

This technique is useful if you need to show a loading state, to avoid the resizing and shifting of the buttons:


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';
import { on } from '@ember/modifier';
import { tracked } from '@glimmer/tracking';
import style from 'ember-style-modifier';

import {
  HdsButton,
  HdsButtonSet,
} from '@hashicorp/design-system-components/components';

export default class LocalComponent extends Component {
  @tracked isLoading = false;
  @tracked timer: ReturnType<typeof setTimeout> | undefined;

  toggleIsLoading = () => {
    this.isLoading = !this.isLoading;

    clearTimeout(this.timer);

    this.timer = setTimeout(() => {
      this.isLoading = false;
    }, 4000);
  };

  cancelLoading = () => {
    this.isLoading = false;
  };

  <template>
    <HdsButtonSet {{style width="15rem"}}>
      <HdsButton
        @icon={{if this.isLoading "loading"}}
        @text={{if this.isLoading "Loading" "Save"}}
        @isFullWidth={{true}}
        {{on "click" this.toggleIsLoading}}
      />
      <HdsButton
        @text="Cancel"
        @color="secondary"
        @isFullWidth={{true}}
        {{on "click" this.cancelLoading}}
      />
    </HdsButtonSet>
  </template>
}
```

```handlebars title="Classic Ember (.hbs)"
<Hds::ButtonSet {{style width="15rem"}}>
  <Hds::Button
    @icon={{if this.isLoading "loading"}}
    @text={{if this.isLoading "Loading" "Save"}}
    @isFullWidth={{true}}
    {{on "click" this.toggleIsLoading}}
  />
  <Hds::Button @text="Cancel" @color="secondary" @isFullWidth={{true}} {{on "click" this.cancelLoading}} />
</Hds::ButtonSet>
```

```javascript title="Classic Ember backing class (.js)"
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { tracked } from '@glimmer/tracking';

export default class LocalComponent extends Component {
  @tracked isLoading = false;
  @tracked timer;

  @action
  toggleIsLoading() {
    this.isLoading = !this.isLoading;

    clearTimeout(this.timer);
    // make it go back to the idle state
    this.timer = setTimeout(() => {
      this.isLoading = false;
    }, 4000);
  }

  @action
  cancelLoading() {
    this.isLoading = false;
  }
}
```

### Interactive states

The `@level`, `@levelHover`, and `@levelActive` arguments can be used to declare the specific elevation of the Card for each interactive state. Following the guidelines, this example transitions between _mid → high → mid_ elevation for the corresponding interactive states; _default → hover → active_.


```gts title="Modern Ember (.gts)"
