      @level="mid"
      @levelHover="high"
      @levelActive="mid"
      @hasBorder={{true}}
    >
      <a href="#">
        [Your static content here]
      </a>
    </HdsCardContainer>
  </div>
</template>;

export default LocalComponent;
```

