```javascript title="Classic Ember backing class (.js)"
import Component from '@glimmer/component';
import { action } from '@ember/object';
import { tracked } from '@glimmer/tracking';
import { service } from '@ember/service';

import USER_DATA from 'website/mocks/user-data';

export default class LocalComponent extends Component {
  @service router;

  @tracked demoPageSizes = [5, 10, 30];

  get model() {
    return { records: USER_DATA };
  }

  get demoRouteName() {
    // eg. 'components.pagination';
    return this.router.currentRouteName ?? '';
  }

  get demoTotalItems() {
    return this.model.records.length;
  }

  get demoCurrentPage() {
    return parseInt(
      this.router?.currentRoute?.queryParams?.demoCurrentPage ?? 1
    );
  }

  get demoCurrentPageSize() {
    return parseInt(
      this.router?.currentRoute?.queryParams?.demoCurrentPageSize ?? 5
    );
  }

  get demoQueryFunctionNumbered() {
    return (page, pageSize) => {
      return {
        // important: in order for this to work, the query param name needs to be added to the list of query params in the controller:
        // see: https://github.com/hashicorp/design-system/blob/main/website/app/controllers/show.js#L42-L53
        demoCurrentPage: page,
        demoCurrentPageSize: pageSize,
        // see: https://github.com/DockYard/ember-router-scroll#preservescrollposition-with-queryparams
        preserveScrollPosition: true,
      };
    };
  }

  @action
  handlePageChange(page, pageSize) {
    console.log(
      pageSize !== undefined
        ? `Page changed to "${page}" with page size equal to "${pageSize}"!`
        : `Page changed to "${page}"!`
    );
  }

  @action
  async handlePageSizeChangeNumbered(pageSize) {
    const routeQueryParams = this?.router?.currentRoute?.queryParams ?? {};
    let queryParams = Object.assign({}, routeQueryParams);
    // the sensible thing to do here is to reset the pagination to the first element (any alternative would result in an unpredictable UX)
    queryParams.demoCurrentPage = 1;
    queryParams.demoCurrentPageSize = pageSize;
    // see: https://github.com/DockYard/ember-router-scroll#preservescrollposition-with-queryparams
    queryParams.preserveScrollPosition = true;
    // navigate to the new URL (notice: the anchor/fragment `#...` is not preserved unfortunately)
    await this.router.transitionTo({ queryParams });
  }
}
```


When the routing parameters are provided, the "navigation controls" are rendered as links and if the user clicks on one of them the page URL is automatically updated. This means that the component’s state is persisted **outside** of the component and so its whole state **must** be "controlled" by the consumer’s code (otherwise there would be conflicting states).


!!! Warning

**Code alert**

When a pagination component is controlled externally, as described above, at least one routing argument (`@route`, `@model`, or `@models`) **must** be provided.
!!!

In this case, the component doesn’t update its internal "state" but the value of the state variables (eg. `currentPage/currentPageSize`) is **always** determined by the consumer’s controller code via the component’s arguments (usually, they are directly connected to the query parameters in the URL).

The reason for using a consumer-side function to determine the `query` argument is because it’s dynamic (it depends on the value of the `page` variable) and gives consumers the ability to specify their own query parameters (which will likely differ case by case).

Even if the Pagination is based on routing, the `onPageChange/onPageSizeChange` callbacks are still available and can be used to respond to the users’ actions (eg. for logging, tracking, etc.).

Below you can find an example of an integration between the sortable [`Table`](/components/table/table) component and the `Pagination::Numbered` component that uses query parameters in the URL to preserve the UI state:


```gts title="Modern Ember (.gts)"
