## Composition with other components

The Stepper Nav should be paired with appropriate navigation [Buttons](/components/button). Buttons can be wrapped with a [Button Set](/components/button-set) to ensure consistent spacing between them.


```gts title="Modern Ember (.gts)"
import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';
import { on } from '@ember/modifier';

import {
  HdsStepperNav,
  HdsButton,
  HdsButtonSet,
} from '@hashicorp/design-system-components/components';

export default class LocalComponent extends Component {
  @tracked demoButtonsCurrentStep = 0;

  demoButtonsOnStepChange = (_event: Event, stepNumber: number) => {
    this.demoButtonsCurrentStep = stepNumber;
  };

  onNextClickDemo = () => {
    this.demoButtonsCurrentStep++;
  };

  onPreviousClickDemo = () => {
    this.demoButtonsCurrentStep--;
  };

  <template>
    <HdsStepperNav
      @currentStep={{this.demoButtonsCurrentStep}}
      @ariaLabel="Component composition"
      @onStepChange={{this.demoButtonsOnStepChange}}
      as |S|
    >
      <S.Step>
        <:title>Step 1</:title>
      </S.Step>
      <S.Step>
        <:title>Step 2</:title>
      </S.Step>
      <S.Step>
        <:title>Step 3</:title>
      </S.Step>
      <S.Panel>
        Content 1
