## Ember engines

If your application uses Ember engines, you have to add a small extra configuration to your `app.js` file:


```javascript
import LinkToExternal from 'ember-engines/components/link-to-external';
import { setLinkToExternal } from '@hashicorp/design-system-components/utils/hds-link-to-external';

setLinkToExternal(LinkToExternal);
```


This allows the [`Hds::Interactive`](/utilities/interactive) utility component, used in multiple HDS components, to access the `<LinkToExternal>` component to generate cross-engines links. For more details about this component API, please refer to [its documentation page](/utilities/interactive?tab=code#component-api).

#### Non-standard gap values

If you absolutely have to use non-standard spacing value(s) for the flex `gap`, you can use the internal `--hds-layout-flex-row-gap` and `--hds-layout-flex-column-gap` CSS variables and pass custom values to them (e.g., via a local CSS class or an inline style).


```gts title="Modern Ember (.gts)"
import type { TemplateOnlyComponent } from '@ember/component/template-only';

import { HdsLayoutFlex } from '@hashicorp/design-system-components/components';

const LocalComponent: TemplateOnlyComponent = <template>
  <HdsLayoutFlex class="doc-flex-demo-custom-flex-column-gap">
    {{!
    // example of CSS code associated with the demo class:
    .doc-flex-demo-custom-flex-column-gap {
      --hds-layout-flex-column-gap: 13px;
    }
  }}
    {{!
    multiple flex items here, with a non-standard gap between them
  }}
  </HdsLayoutFlex>
</template>;

export default LocalComponent;
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Layout::Flex class="doc-flex-demo-custom-flex-column-gap">
  {{!
    // example of CSS code associated with the demo class:
    .doc-flex-demo-custom-flex-column-gap {
      --hds-layout-flex-column-gap: 13px;
    }
  }}
  {{!
    multiple flex items here, with a non-standard gap between them
  }}
</Hds::Layout::Flex>
```


If the flex items are wrapping to multiple lines, you have to overwrite both the "row" and "column" gap values:


```gts title="Modern Ember (.gts)"
import type { TemplateOnlyComponent } from '@ember/component/template-only';
import style from 'ember-style-modifier';

import { HdsLayoutFlex } from '@hashicorp/design-system-components/components';

const LocalComponent: TemplateOnlyComponent = <template>
  <HdsLayoutFlex
    {{style
      --hds-layout-flex-row-gap="10px"
      --hds-layout-flex-column-gap="0.625rem"
    }}
    @wrap={{true}}
  >
    {{!
    multiple flex items appearing on multiple rows
    with a vertical gap of 10px and an horizontal one of 0.625rem
  }}
  </HdsLayoutFlex>
</template>;

export default LocalComponent;
```

```handlebars title="Classic Ember (.hbs)"
<Hds::Layout::Flex {{style --hds-layout-flex-row-gap="10px" --hds-layout-flex-column-gap="0.625rem"}} @wrap={{true}}>
