            <A.Item>
              <:toggle>{{overflowFilter.label}}</:toggle>
              <:content>
                <Hds::Form::Checkbox::Group @name={{overflowFilter.label}} as |G|>
                  {{#each overflowFilter.values as |value|}}
                    <G.CheckboxField as |F|>
                      <F.Label>{{value.name}}</F.Label>
                    </G.CheckboxField>
                  {{/each}}
                </Hds::Form::Checkbox::Group>
              </:content>
            </A.Item>
          {{/each}}
        </Hds::Accordion>
      </F.Body>
      <F.Footer>
        <Hds::ButtonSet>
          <Hds::Button @color="primary" @text="Apply filters" {{on "click" this.deactivateFlyout}} />
          <Hds::Button @text="Cancel" @color="secondary" {{on "click" this.deactivateFlyout}} />
        </Hds::ButtonSet>
      </F.Footer>
    </Hds::Flyout>
  {{/if}}

  <Hds::Accordion @size="small" @type="card" as |A|>
    <A.Item @containsInteractive={{true}}>
      <:toggle>
        <div class="doc-filter-patterns-accordion-toggle">
          <Hds::Text::Body @color="strong" @size="200" @weight="semibold">Applied filters (25)</Hds::Text::Body>
          <Hds::Button
            @size="small"
            @color="tertiary"
            @icon="x"
            @iconPosition="leading"
            @text="Clear all filters"
            {{on "click" this.clearAllFilters}}
          />
        </div>
      </:toggle>
      <:content>
        <div class="doc-filter-patterns-applied-filters">
          {{#each this.model.demoAppliedFilters as |appliedFilter|}}
            <Hds::Tag @text={{appliedFilter}} @onDismiss={{this.filterDismissFunction}} />
          {{/each}}
        </div>
      </:content>
    </A.Item>
  </Hds::Accordion>
</div>
```

